 for(let i=0;i<12;i++){const a=i*Math.PI/6;const rib=box(Math.cos(a)*5.4,5,Math.sin(a)*5.4,.5,7.7,1,'#ced9d3',reactor);rib.rotation.y=-a;const window=box(Math.cos(a)*4.65,5.3,Math.sin(a)*4.65,.38,4.5,.18,'#87d9d3',reactor);window.rotation.y=-a;window.material.emissive.set('#609f9d');window.material.emissiveIntensity=.45;}
