 for(const r of plan.rooms){const floor=box(r.x,.12,r.z,r.w,.18,r.d,colors[r.kind]);floor.userData.inspect={title:r.name,kind:'Connected compartment',description:r.kind==='quarters'?'Five assigned personal berths opening onto the reactor-side gallery.':'Stock interior equipment at authored metre scale. Crew visits are tracked; machinery output is not simulated.'};floor.userData.liveReadout=()=>`${sim.state.crew.filter(p=>p.room===r.id&&p.phase!=='walking').length} crew currently here`;
  if(r.side){for(const sign of [-1,1]){box(r.x,.65,r.z+sign*r.d/2,r.w,1.1,.22,'#d9dfd9');box(r.x,1.95,r.z+sign*r.d/2,r.w,1.5,.22,'#d9dfd9',roof);}const outer=r.x+r.side*r.w/2,inner=r.x-r.side*r.w/2;box(outer,.85,r.z,.25,1.6,r.d,'#d5dcd8');box(outer,2.2,r.z,.25,1.1,r.d,'#d5dcd8',roof);for(const sign of [-1,1]){box(inner,.65,r.z+sign*(r.d/4+.65),.22,1.1,r.d/2-1.3,'#d9dfd9');box(inner,1.95,r.z+sign*(r.d/4+.65),.22,1.5,r.d/2-1.3,'#d9dfd9',roof);}box(inner,2.5,r.z,.22,.4,2.6,'#d9dfd9',roof);}
  else{for(const x of [-r.w/2,r.w/2]){box(x,.85,r.z,.22,1.6,r.d,'#d5dcd8');box(x,2.2,r.z,.22,1.1,r.d,'#d5dcd8',roof);}const sign=r.id==='bridge'?-1:1;box(0,.85,r.z+sign*r.d/2,r.w,1.6,.22,'#d5dcd8');box(0,2.2,r.z+sign*r.d/2,r.w,1.1,.22,'#d5dcd8',roof);for(const x of [-6.9,6.9])box(x,.65,r.z-sign*r.d/2,10.2,1.1,.2,'#d9dfd9');}
  box(r.x,2.8,r.z,r.w,.2,r.d,'#e2e5df',roof);
  const canvas=document.createElement('canvas');canvas.width=512;canvas.height=80;const ctx=canvas.getContext('2d');ctx.fillStyle='#263b43';ctx.font='600 30px sans-serif';ctx.textAlign='center';ctx.fillText(r.name.toUpperCase(),256,48);const texture=new T.CanvasTexture(canvas),label=new T.Mesh(new T.PlaneGeometry(8,1.25),new T.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false}));label.rotation.x=-Math.PI/2;label.position.set(r.x,.225,r.z+3.7);label.userData.inspect=floor.userData.inspect;label.userData.liveReadout=floor.userData.liveReadout;root.add(label);owned.push(label);
 }
 for(const side of [-1,1])for(const fore of [-1,1])box(side*8,.17,fore*23,10,.08,7,'#60797d');
