 for(let i=0;i<20;i++){const body=model(['RI-007','SI-007','MI-007'][i%3]);body.userData.storyId=sim.state.crew[i].id;body.userData.inspect={title:sim.state.crew[i].name,kind:'Aurora crew',description:'Assigned berth '+(i+1)+' · saved identity and compartment visits.'};root.add(body);actors.push({body,get phase(){return sim.state.crew[i].phase;}});}
