 present();const life={get state(){return sim.state;},workers:actors,places:plan.rooms,update(dt){sim.update(dt);present();},snapshot:()=>sim.snapshot(),restore(s){sim=createStarshipSimulation(seed,s);present();},summary:()=>({crew:20,berths:20,visits:sim.state.visits,meals:sim.state.meals,food:sim.state.stock.food,water:sim.state.stock.water,balance:sim.balance()}),navigation:()=>({workers:sim.state.crew.map(p=>({...p.position,phase:p.phase,room:p.room})),rooms:plan.rooms.length}),describePlace:()=>'',dispose(){},notices:()=>[],get readout(){return `${sim.state.visits} compartment visits · ${sim.state.meals} meals · ${sim.state.stock.food.toFixed(1)} food · ${sim.state.stock.water.toFixed(1)} water`;}};
